<?php
require_once __DIR__.'/requirement_document_common.php';$user=rdUser();
try{if($_SERVER['REQUEST_METHOD']!=='POST')rdResponse(['success'=>false,'error'=>'Methode nicht erlaubt.'],405);$d=rdBody();$project=trim((string)($d['project_id']??''));$title=trim((string)($d['title']??''));$type=strtoupper(trim((string)($d['requirement_type']??'SYS')));if($title==='')rdResponse(['success'=>false,'error'=>'Titel fehlt.'],422);$p=$pdo->prepare('SELECT id FROM projects WHERE id=?');$p->execute([$project]);if(!$p->fetchColumn())rdResponse(['success'=>false,'error'=>'Projekt nicht gefunden.'],404);if(!in_array($type,['DOC','USR','SYS','SEC','SRS','HRS','SWC','TC','TR'],true))rdResponse(['success'=>false,'error'=>'Ungültiger Typ.'],422);
$blocks=[];$meta=['status'=>'Open','priority'=>'Medium','relevance'=>'Must','review_status'=>'New'];$tid=trim((string)($d['template_id']??''));if($tid!==''){$t=$pdo->prepare('SELECT blocks,default_metadata FROM requirement_document_templates WHERE id=? AND is_active=1 AND(project_id IS NULL OR project_id=?)');$t->execute([$tid,$project]);$r=$t->fetch(PDO::FETCH_ASSOC);if(!$r)rdResponse(['success'=>false,'error'=>'Vorlage nicht gefunden.'],404);$blocks=json_decode($r['blocks'],true)?:[];$meta=array_replace($meta,json_decode($r['default_metadata']??'{}',true)?:[]);}
$pdo->beginTransaction();$pdo->prepare('INSERT INTO requirement_document_sequences(project_id,requirement_type,last_number)VALUES(?,?,1)ON DUPLICATE KEY UPDATE last_number=last_number+1')->execute([$project,$type]);$n=$pdo->prepare('SELECT last_number FROM requirement_document_sequences WHERE project_id=? AND requirement_type=? FOR UPDATE');$n->execute([$project,$type]);$key=$type.'-'.str_pad((string)$n->fetchColumn(),3,'0',STR_PAD_LEFT);$id=rdUuid();$pdo->prepare('INSERT INTO requirement_documents(id,project_id,requirement_key,requirement_type,title,status,priority,relevance,review_status,metadata,created_by,updated_by)VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$project,$key,$type,$title,$meta['status'],$meta['priority'],$meta['relevance'],$meta['review_status'],json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$user,$user]);$i=$pdo->prepare('INSERT INTO requirement_document_blocks(id,document_id,block_type,content,sort_order)VALUES(?,?,?,?,?)');foreach(array_values($blocks)as$pos=>$b){if(!is_array($b))continue;$data=$b['data']??[];if(($b['type']??'')==='heading')$data['level']=max(3,min(5,(int)($data['level']??3)));$i->execute([rdUuid(),$id,(string)($b['type']??'text'),json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$pos]);}$pdo->commit();rdResponse(['success'=>true,'id'=>$id,'requirement_key'=>$key],201);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();rdResponse(['success'=>false,'error'=>$e->getMessage()],500);}
